// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address oldOwner = c.owner();
        vm.prank(oldOwner);
        try c.transferOwnership(newOwner) {
            assertTrue(c.owner() == newOwner, "ownership must be transferred");
        } catch {
            assertTrue(false, "transferOwnership must succeed for owner");
        }
    }
}
